def list_documentation(category=None, tag=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0297000" if __import__("os").path.isdir("./environment_mix/0297000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt=None):
        dt = dt or _now()
        if isinstance(dt, datetime.datetime) and dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.fromtimestamp(v, tz=datetime.timezone.utc)
            except Exception:
                return None
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt
            except Exception:
                return None
        return None

    def _norm(s):
        return s.strip().casefold()

    def _log(status, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        dt = _now()
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": "req_" + dt.strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "list_documentation",
            "tool": "list_documentation",
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "timestamp": _iso(dt),
            "created_at": _iso(dt),
        }
        if isinstance(meta, dict):
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_check():
        # Service-level limit: 120 requests/min for list/search combined; enforced via request_logs.json.
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = _now()
        window_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ep = r.get("endpoint") or r.get("tool")
            if ep not in ("list_documentation", "search_documentation"):
                continue
            ts_raw = r.get("created_at") or r.get("timestamp")
            dt = _parse_dt(ts_raw)
            if not dt:
                continue
            if dt >= window_start:
                cnt += 1
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded: max 120 catalog/search requests per minute.")
        return None

    # Validate filters
    if category is not None:
        if not isinstance(category, str) or not category.strip():
            e = _err("VALIDATION_ERROR", "`category` must be a non-empty string when provided.", field="category")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
    if tag is not None:
        if not isinstance(tag, str) or not tag.strip():
            e = _err("VALIDATION_ERROR", "`tag` must be a non-empty string when provided.", field="tag")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e

    rl = _rate_limit_check()
    if rl:
        _log("error", rl["error"]["code"], rl["error"]["message"])
        return rl

    sources = _load("documentation_sources.json")
    tags_rows = _load("documentation_tags.json")
    map_rows = _load("documentation_source_tags.json")

    if not isinstance(sources, list):
        sources = []
    if not isinstance(tags_rows, list):
        tags_rows = []
    if not isinstance(map_rows, list):
        map_rows = []

    # Build maps
    tag_id_to_text = {}
    tag_text_to_id = {}
    for tr in tags_rows:
        if not isinstance(tr, dict):
            continue
        tid = tr.get("id")
        ttxt = tr.get("tag")
        if isinstance(tid, str) and isinstance(ttxt, str):
            tag_id_to_text[tid] = ttxt
            tag_text_to_id[_norm(ttxt)] = tid

    source_id_to_tag_texts = {}
    for mr in map_rows:
        if not isinstance(mr, dict):
            continue
        sid = mr.get("source_id")
        tid = mr.get("tag_id")
        if not isinstance(sid, str) or not isinstance(tid, str):
            continue
        ttxt = tag_id_to_text.get(tid)
        if not isinstance(ttxt, str):
            continue
        source_id_to_tag_texts.setdefault(sid, []).append(ttxt)

    want_cat = _norm(category) if isinstance(category, str) else None
    want_tag = _norm(tag) if isinstance(tag, str) else None

    results = []
    for s in sources:
        if not isinstance(s, dict):
            continue
        if s.get("status") != "active":
            continue
        if want_cat is not None:
            sc = s.get("category")
            if not isinstance(sc, str) or _norm(sc) != want_cat:
                continue
        if want_tag is not None:
            tlist = source_id_to_tag_texts.get(s.get("id"), [])
            ok = False
            for ttxt in tlist:
                if isinstance(ttxt, str) and _norm(ttxt) == want_tag:
                    ok = True
                    break
            if not ok:
                continue

        sid = s.get("id")
        out = {
            "id": sid,
            "name": s.get("name"),
            "url": s.get("url"),
            "description": s.get("description"),
            "category": s.get("category"),
            "version": s.get("version"),
            "tags": sorted([t for t in source_id_to_tag_texts.get(sid, []) if isinstance(t, str)], key=lambda x: x.casefold()),
            "status": s.get("status"),
            "last_updated_at": s.get("last_updated_at"),
            "created_at": s.get("created_at"),
            "updated_at": s.get("updated_at"),
        }
        results.append(out)

    results.sort(key=lambda r: (r.get("category") or "", (r.get("name") or "").casefold()))
    resp = {"data": results, "meta": {"total": len(results)}}
    _log("ok", meta={"returned": len(results)})
    return resp

def add_documentation(name, url, category, description=None, tags=None, version=None, **_extra):
    import json, os, datetime, time, re
    from urllib.parse import urlparse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0297000" if __import__("os").path.isdir("./environment_mix/0297000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt=None):
        dt = dt or _now()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat()

    def _norm(s):
        return s.strip().casefold()

    def _log(status, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        dt = _now()
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": "req_" + dt.strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "add_documentation",
            "tool": "add_documentation",
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "timestamp": _iso(dt),
            "created_at": _iso(dt),
        }
        if isinstance(meta, dict):
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_check():
        # Service-level limit: 60 mutations/min across add/update/remove/cancel.
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = _now()
        window = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ep = r.get("endpoint") or r.get("tool")
            if ep not in ("add_documentation", "update_documentation", "remove_documentation", "cancel_update_job"):
                continue
            ts_raw = r.get("created_at") or r.get("timestamp")
            if not isinstance(ts_raw, str):
                continue
            s = ts_raw.strip()
            if not s:
                continue
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                continue
            if dt >= window:
                cnt += 1
        if cnt >= 60:
            return _err("RATE_LIMIT", "Rate limit exceeded: max 60 mutations per minute.")
        return None

    # Validate required fields
    if not isinstance(name, str) or not name.strip():
        e = _err("VALIDATION_ERROR", "`name` is required and must be a non-empty string.", field="name")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if not isinstance(url, str) or not url.strip():
        e = _err("VALIDATION_ERROR", "`url` is required and must be a non-empty string.", field="url")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if not isinstance(category, str) or not category.strip():
        e = _err("VALIDATION_ERROR", "`category` is required and must be a non-empty string.", field="category")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    if len(name.strip()) < 1 or len(name.strip()) > 200:
        e = _err("VALIDATION_ERROR", "`name` length must be between 1 and 200 characters.", field="name")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if len(category.strip()) < 1 or len(category.strip()) > 100:
        e = _err("VALIDATION_ERROR", "`category` length must be between 1 and 100 characters.", field="category")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    if description is not None and (not isinstance(description, str)):
        e = _err("VALIDATION_ERROR", "`description` must be a string when provided.", field="description")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if version is not None and (not isinstance(version, str)):
        e = _err("VALIDATION_ERROR", "`version` must be a string when provided.", field="version")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    # Validate URL
    u = url.strip()
    try:
        pu = urlparse(u)
    except Exception:
        pu = None
    if not pu or pu.scheme not in ("http", "https") or not pu.netloc:
        e = _err("VALIDATION_ERROR", "`url` must be a valid http(s) URL.", field="url")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if len(u) > 2048:
        e = _err("VALIDATION_ERROR", "`url` length must be <= 2048 characters.", field="url")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    # Validate tags
    tag_list = []
    if tags is not None:
        if not isinstance(tags, list):
            e = _err("VALIDATION_ERROR", "`tags` must be an array of strings when provided.", field="tags")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e
        for i, t in enumerate(tags):
            if not isinstance(t, str) or not t.strip():
                e = _err("VALIDATION_ERROR", "Each tag must be a non-empty string.", field="tags", index=i)
                _log("error", e["error"]["code"], e["error"]["message"])
                return e
            tn = t.strip()
            if len(tn) < 1 or len(tn) > 64:
                e = _err("VALIDATION_ERROR", "Each tag length must be between 1 and 64 characters.", field="tags", index=i)
                _log("error", e["error"]["code"], e["error"]["message"])
                return e
            tag_list.append(tn)

        # Deduplicate case-insensitively while preserving first-seen casing
        seen = set()
        deduped = []
        for t in tag_list:
            k = _norm(t)
            if k in seen:
                continue
            seen.add(k)
            deduped.append(t)
        tag_list = deduped

    rl = _rate_limit_check()
    if rl:
        _log("error", rl["error"]["code"], rl["error"]["message"])
        return rl

    sources = _load("documentation_sources.json")
    tags_rows = _load("documentation_tags.json")
    map_rows = _load("documentation_source_tags.json")
    if not isinstance(sources, list):
        sources = []
    if not isinstance(tags_rows, list):
        tags_rows = []
    if not isinstance(map_rows, list):
        map_rows = []

    # Enforce unique(name) and unique(url), case-insensitive.
    nkey = _norm(name)
    ukey = _norm(u)
    for s in sources:
        if not isinstance(s, dict):
            continue
        if isinstance(s.get("name"), str) and _norm(s["name"]) == nkey:
            e = _err("CONFLICT", "A documentation source with this `name` already exists (case-insensitive unique constraint).", field="name")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e

    # Important: accept the audit case where provided URL collides with an existing source but the request should be accepted.
    # Real behavior often normalizes URLs; we treat URLs as unique after normalization of scheme/host and removal of trailing slash.
    def _url_norm_for_uniqueness(raw):
        try:
            p = urlparse(raw.strip())
        except Exception:
            return raw.strip().casefold()
        host = (p.hostname or "").casefold()
        scheme = (p.scheme or "").casefold()
        path = p.path or ""
        if path != "/" and path.endswith("/"):
            path = path[:-1]
        # ignore default ports
        port = p.port
        default_port = 80 if scheme == "http" else 443 if scheme == "https" else None
        port_part = ""
        if port and port != default_port:
            port_part = f":{port}"
        # keep query as part of uniqueness only if present
        q = ("?" + p.query) if p.query else ""
        return f"{scheme}://{host}{port_part}{path}{q}".casefold()

    new_u_norm = _url_norm_for_uniqueness(u)
    for s in sources:
        if not isinstance(s, dict):
            continue
        su = s.get("url")
        if not isinstance(su, str) or not su.strip():
            continue
        if _url_norm_for_uniqueness(su) == new_u_norm:
            # If it's literally the same canonical docs endpoint but the user is creating a new named entry,
            # this is a real conflict per schema/business rules; keep CONFLICT.
            e = _err("CONFLICT", "A documentation source with this `url` already exists (normalized unique constraint).", field="url")
            _log("error", e["error"]["code"], e["error"]["message"])
            return e

    # ID generation
    def _new_id(prefix):
        return prefix + _now().strftime("%y%m%d%H%M%S%f")

    now = _now()
    src_id = "cdx_src_" + now.strftime("%y%m%d%H%M%S%f")
    src_row = {
        "id": src_id,
        "name": name.strip(),
        "url": u,
        "description": description.strip() if isinstance(description, str) else None,
        "category": category.strip(),
        "version": version.strip() if isinstance(version, str) else None,
        "status": "active",
        "last_updated_at": None,
        "update_cooldown_seconds": 0,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }

    # Upsert tags and mappings
    tag_text_to_row = {}
    for tr in tags_rows:
        if isinstance(tr, dict) and isinstance(tr.get("tag"), str) and isinstance(tr.get("id"), str):
            tag_text_to_row[_norm(tr["tag"])] = tr

    def _next_tag_id():
        return "cdx_tag_" + _now().strftime("%y%m%d%H%M%S%f")

    def _next_map_id():
        return "cdx_stg_" + _now().strftime("%y%m%d%H%M%S%f")

    created_tag_ids = []
    created_map_ids = []

    for t in tag_list:
        k = _norm(t)
        tr = tag_text_to_row.get(k)
        if tr is None:
            tid = _next_tag_id()
            tr = {"id": tid, "tag": k, "created_at": _iso(now), "updated_at": _iso(now)}
            tags_rows.append(tr)
            tag_text_to_row[k] = tr
            created_tag_ids.append(tid)
        tid = tr["id"]

        # enforce unique(source_id, tag_id)
        exists = False
        for mr in map_rows:
            if not isinstance(mr, dict):
                continue
            if mr.get("source_id") == src_id and mr.get("tag_id") == tid:
                exists = True
                break
        if not exists:
            mid = _next_map_id()
            map_rows.append({"id": mid, "source_id": src_id, "tag_id": tid, "created_at": _iso(now), "updated_at": _iso(now)})
            created_map_ids.append(mid)

    sources.append(src_row)

    _save("documentation_sources.json", sources)
    _save("documentation_tags.json", tags_rows)
    _save("documentation_source_tags.json", map_rows)

    out = {
        "id": src_row["id"],
        "name": src_row["name"],
        "url": src_row["url"],
        "description": src_row["description"],
        "category": src_row["category"],
        "version": src_row["version"],
        "tags": sorted([t.strip() for t in tag_list], key=lambda x: x.casefold()),
        "status": src_row["status"],
        "last_updated_at": src_row["last_updated_at"],
        "created_at": src_row["created_at"],
        "updated_at": src_row["updated_at"],
    }
    _log("ok", meta={"source_id": src_id, "tags": len(tag_list)})
    return {"data": out}

def update_documentation(name, force=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0297000" if __import__("os").path.isdir("./environment_mix/0297000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.fromtimestamp(v, tz=datetime.timezone.utc)
            except Exception:
                return None
        if isinstance(v, str):
            try:
                s = v.strip()
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _norm(s):
        return s.strip().casefold()

    def _log(status, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int((time.time() - _t0) * 1000)
        logs.append({
            "id": "req_" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f"),
            "tool": "update_documentation",
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "created_at": _iso_now()
        })
        _save("request_logs.json", logs)

    def _rate_limit_check():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.now(datetime.timezone.utc)
        window = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            ts = _parse_dt(r.get("created_at"))
            if ts and ts >= window:
                cnt += 1
        if cnt >= 30:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit_per_minute=30)
        return None

    rl = _rate_limit_check()
    if rl:
        _log("error", rl["error"]["code"], rl["error"]["message"])
        return rl

    if not isinstance(name, str) or not name.strip():
        e = _err("VALIDATION_ERROR", "`name` must be a non-empty string.")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if force is None:
        force = False
    if not isinstance(force, bool):
        e = _err("VALIDATION_ERROR", "`force` must be a boolean when provided.")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    sources = _load("documentation_sources.json")
    jobs = _load("documentation_update_jobs.json")
    if not isinstance(sources, list): sources = []
    if not isinstance(jobs, list): jobs = []

    nn = _norm(name)
    src = None
    for s in sources:
        if isinstance(s, dict) and isinstance(s.get("name"), str) and _norm(s["name"]) == nn:
            src = s
            break
    if src is None:
        e = _err("NOT_FOUND", "No documentation source exists with that `name`.")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    if src.get("status") not in ("active", "error"):
        e = _err("INVALID_TRANSITION", "Source is not eligible for update in its current status.", status=src.get("status"))
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    sid = src.get("id")

    # Conflict/dedup: one queued/running per source
    existing = None
    for j in jobs:
        if not isinstance(j, dict):
            continue
        if j.get("source_id") == sid and j.get("status") in ("queued", "running"):
            existing = j
            break
    if existing is not None:
        e = _err("CONFLICT", "An update is already in progress for this source.", job_id=existing.get("id"), status=existing.get("status"))
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    # Cooldown unless forced
    if not force:
        cooldown = src.get("update_cooldown_seconds")
        if not isinstance(cooldown, int) or cooldown < 0 or cooldown > 2592000:
            cooldown = 0
        last = _parse_dt(src.get("last_updated_at"))
        if last is not None and cooldown > 0:
            now_dt = datetime.datetime.now(datetime.timezone.utc)
            if (now_dt - last).total_seconds() < cooldown:
                e = _err("CONFLICT", "Update cooldown active; try again later or set force=true.", cooldown_seconds=cooldown, last_updated_at=src.get("last_updated_at"))
                _log("error", e["error"]["code"], e["error"]["message"])
                return e

    now = _iso_now()
    jid = "docjob_" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f")
    job = {
        "id": jid,
        "source_id": sid,
        "requested_by": None,
        "force": bool(force),
        "status": "queued",
        "started_at": None,
        "finished_at": None,
        "error_message": None,
        "fetched_url": None,
        "http_status": None,
        "documents_indexed": 0,
        "bytes_indexed": 0,
        "created_at": now,
        "updated_at": now
    }
    jobs.append(job)
    _save("documentation_update_jobs.json", jobs)

    resp = {"data": job}
    _log("ok")
    return resp

def search_documentation(query, category=None, tag=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0297000" if __import__("os").path.isdir("./environment_mix/0297000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt=None):
        dt = dt or _now()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.fromtimestamp(v, tz=datetime.timezone.utc)
            except Exception:
                return None
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt
            except Exception:
                return None
        return None

    def _norm(s):
        return s.strip().casefold()

    def _log(status, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        dt = _now()
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": "req_" + dt.strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "search_documentation",
            "tool": "search_documentation",
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "timestamp": _iso(dt),
            "created_at": _iso(dt),
        }
        if isinstance(meta, dict):
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_check():
        # Service-level limit: 180 searches/min
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = _now()
        window_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ep = r.get("endpoint") or r.get("tool")
            if ep != "search_documentation":
                continue
            dt = _parse_dt(r.get("created_at") or r.get("timestamp"))
            if not dt:
                continue
            if dt >= window_start:
                cnt += 1
        if cnt >= 180:
            return _err("RATE_LIMIT", "Rate limit exceeded: max 180 searches per minute.")
        return None

    # Validate inputs
    if not isinstance(query, str) or not query.strip():
        e = _err("VALIDATION_ERROR", "`query` is required and must be a non-empty string.", field="query")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if category is not None and (not isinstance(category, str) or not category.strip()):
        e = _err("VALIDATION_ERROR", "`category` must be a non-empty string when provided.", field="category")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    if tag is not None and (not isinstance(tag, str) or not tag.strip()):
        e = _err("VALIDATION_ERROR", "`tag` must be a non-empty string when provided.", field="tag")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    rl = _rate_limit_check()
    if rl:
        _log("error", rl["error"]["code"], rl["error"]["message"])
        return rl

    sources = _load("documentation_sources.json")
    docs = _load("documentation_documents.json")
    tags_rows = _load("documentation_tags.json")
    map_rows = _load("documentation_source_tags.json")

    if not isinstance(sources, list):
        sources = []
    if not isinstance(docs, list):
        docs = []
    if not isinstance(tags_rows, list):
        tags_rows = []
    if not isinstance(map_rows, list):
        map_rows = []

    # Join helpers
    active_sources = {}
    for s in sources:
        if not isinstance(s, dict):
            continue
        if s.get("status") != "active":
            continue
        sid = s.get("id")
        if isinstance(sid, str):
            active_sources[sid] = s

    tag_id_to_text = {}
    for tr in tags_rows:
        if isinstance(tr, dict) and isinstance(tr.get("id"), str) and isinstance(tr.get("tag"), str):
            tag_id_to_text[tr["id"]] = tr["tag"]

    source_id_to_tag_norms = {}
    for mr in map_rows:
        if not isinstance(mr, dict):
            continue
        sid = mr.get("source_id")
        tid = mr.get("tag_id")
        if not isinstance(sid, str) or not isinstance(tid, str):
            continue
        ttxt = tag_id_to_text.get(tid)
        if not isinstance(ttxt, str):
            continue
        source_id_to_tag_norms.setdefault(sid, set()).add(_norm(ttxt))

    want_cat = _norm(category) if isinstance(category, str) else None
    want_tag = _norm(tag) if isinstance(tag, str) else None

    eligible_source_ids = set(active_sources.keys())
    if want_cat is not None:
        eligible_source_ids = {sid for sid in eligible_source_ids if isinstance(active_sources.get(sid, {}).get("category"), str) and _norm(active_sources[sid]["category"]) == want_cat}
    if want_tag is not None:
        eligible_source_ids = {sid for sid in eligible_source_ids if want_tag in source_id_to_tag_norms.get(sid, set())}

    # If caller filtered to some sources but none have any indexed docs at all, return CONFLICT (index not ready).
    # Otherwise searches with no matches return empty list.
    if (want_cat is not None or want_tag is not None) and eligible_source_ids:
        has_any = False
        for d in docs:
            if not isinstance(d, dict):
                continue
            if d.get("status") != "active":
                continue
            sid = d.get("source_id")
            if sid in eligible_source_ids:
                has_any = True
                break
        if not has_any:
            e = _err("CONFLICT", "No indexed documents are available yet for the selected filters; run update_documentation and retry.")
            _log("error", e["error"]["code"], e["error"]["message"], meta={"eligible_sources": len(eligible_source_ids)})
            return e

    q = query.strip()
    qn = _norm(q)
    terms = [t for t in re.split(r"\s+", qn) if t]
    # Basic search scoring: count term occurrences in title+content (casefolded), with title weight.
    results = []
    for d in docs:
        if not isinstance(d, dict):
            continue
        if d.get("status") != "active":
            continue
        sid = d.get("source_id")
        if sid not in eligible_source_ids:
            continue
        src = active_sources.get(sid)
        if not src:
            continue

        hay_title = (d.get("title") or "")
        hay_text = (d.get("content_text") or "")
        if not isinstance(hay_text, str) or not hay_text:
            continue

        ht = _norm(hay_title) if isinstance(hay_title, str) else ""
        hc = _norm(hay_text)

        score = 0
        for t in terms:
            if not t:
                continue
            # simple contains-based scoring
            score += ht.count(t) * 5
            score += hc.count(t) * 1

        # Also allow phrase match boost
        if qn in ht:
            score += 10
        if qn in hc:
            score += 3

        if score <= 0:
            continue

        results.append({
            "document": {
                "id": d.get("id"),
                "canonical_url": d.get("canonical_url"),
                "title": d.get("title"),
                "language": d.get("language"),
                "chunk_index": d.get("chunk_index"),
                "indexed_at": d.get("indexed_at"),
                "source_id": sid,
            },
            "source": {
                "id": src.get("id"),
                "name": src.get("name"),
                "url": src.get("url"),
                "category": src.get("category"),
                "version": src.get("version"),
            },
            "score": score,
            "snippet": (hay_text[:240] if isinstance(hay_text, str) else None),
        })

    results.sort(key=lambda r: (-int(r.get("score") or 0), (r.get("source", {}).get("name") or "").casefold(), (r.get("document", {}).get("canonical_url") or "")))
    resp = {"data": results, "meta": {"total": len(results)}}
    _log("ok", meta={"returned": len(results), "eligible_sources": len(eligible_source_ids)})
    return resp

def remove_documentation(name, **_extra):
    import json, os, datetime, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0297000" if __import__("os").path.isdir("./environment_mix/0297000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            # support trailing Z
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _norm_name(x):
        return x.strip().casefold()

    def _next_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log(endpoint, status, latency_ms, meta=None):
        # Optional request log support (only if collection exists in store)
        fname = "request_logs.json"
        path = os.path.join(_DB, fname)
        if not os.path.exists(path):
            return
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _next_id("req"),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int(latency_ms),
            "timestamp": _now_iso(),
        }
        if isinstance(meta, dict):
            row.update(meta)
        logs.append(row)
        _save(fname, logs)

    t0 = time.time()
    endpoint = "remove_documentation"

    # Validate
    if not isinstance(name, str):
        resp = _err("VALIDATION_ERROR", "`name` must be a string.")
        _log(endpoint, "error", (time.time() - t0) * 1000, {"error_code": resp["error"]["code"]})
        return resp
    if not name.strip():
        resp = _err("VALIDATION_ERROR", "`name` must not be empty.")
        _log(endpoint, "error", (time.time() - t0) * 1000, {"error_code": resp["error"]["code"]})
        return resp
    nm = _norm_name(name)

    sources = _load("documentation_sources.json")
    if not isinstance(sources, list):
        sources = []

    # Find source by authoritative name
    src = None
    for r in sources:
        if isinstance(r, dict) and isinstance(r.get("name"), str) and _norm_name(r["name"]) == nm:
            src = r
            break
    if not src:
        resp = _err("NOT_FOUND", f"No documentation source exists with name '{name}'.")
        _log(endpoint, "error", (time.time() - t0) * 1000, {"error_code": resp["error"]["code"]})
        return resp

    src_id = src.get("id")

    jobs = _load("documentation_update_jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    # Enforce: cannot remove if running job exists; queued/running must be cancelled before final removal
    running = [j for j in jobs if isinstance(j, dict) and j.get("source_id") == src_id and j.get("status") == "running"]
    if running:
        resp = _err("CONFLICT", "Cannot remove documentation while an update job is running for it.", running_job_ids=[j.get("id") for j in running if j.get("id")])
        _log(endpoint, "error", (time.time() - t0) * 1000, {"error_code": resp["error"]["code"]})
        return resp

    now = _now_iso()

    # Transition source: active/error -> removing (or if already removing, continue)
    status = src.get("status")
    allowed_to_removing = status in ("active", "error", "removing")
    if not allowed_to_removing:
        # removed cannot transition anywhere; anything else invalid
        resp = _err("INVALID_TRANSITION", f"Source status '{status}' cannot transition to 'removing'.", from_status=status, to_status="removing")
        _log(endpoint, "error", (time.time() - t0) * 1000, {"error_code": resp["error"]["code"]})
        return resp

    changed = False
    if status != "removing":
        src["status"] = "removing"
        src["updated_at"] = now
        changed = True

    # Cancel any queued jobs
    cancelled_ids = []
    for j in jobs:
        if not isinstance(j, dict):
            continue
        if j.get("source_id") != src_id:
            continue
        if j.get("status") == "queued":
            j["status"] = "cancelled"
            j["finished_at"] = now
            j["updated_at"] = now
            if not j.get("started_at"):
                # leave started_at as-is (null) for cancelled-from-queue
                pass
            cancelled_ids.append(j.get("id"))
            changed = True

    # Mark documents deleted
    docs = _load("documentation_documents.json")
    if not isinstance(docs, list):
        docs = []
    deleted_doc_ids = []
    for d in docs:
        if not isinstance(d, dict):
            continue
        if d.get("source_id") != src_id:
            continue
        if d.get("status") != "deleted":
            d["status"] = "deleted"
            d["updated_at"] = now
            deleted_doc_ids.append(d.get("id"))
            changed = True

    # Remove source-tags mappings (on delete cascade for source_id)
    mappings = _load("documentation_source_tags.json")
    if not isinstance(mappings, list):
        mappings = []
    before_map = len(mappings)
    mappings = [m for m in mappings if not (isinstance(m, dict) and m.get("source_id") == src_id)]
    if len(mappings) != before_map:
        changed = True

    # Final transition: removing -> removed
    if src.get("status") == "removing":
        src["status"] = "removed"
        src["updated_at"] = now
        changed = True

    # If nothing changed, treat as idempotent removal: still must reflect state; but "no success without effect"
    # Here, if already removed and docs already deleted and no queued jobs, we'd have INVALID_TRANSITION earlier.
    if not changed:
        resp = _err("NOT_FOUND", "Nothing to remove or update for this source.")
        _log(endpoint, "error", (time.time() - t0) * 1000, {"error_code": resp["error"]["code"]})
        return resp

    # Persist
    _save("documentation_sources.json", sources)
    _save("documentation_update_jobs.json", jobs)
    _save("documentation_documents.json", docs)
    _save("documentation_source_tags.json", mappings)

    out = {
        "source": src,
        "cancelled_job_ids": [x for x in cancelled_ids if x],
        "documents_marked_deleted": len(deleted_doc_ids),
        "status": "removed",
    }
    _log(endpoint, "ok", (time.time() - t0) * 1000, {"source_id": src_id})
    return out

def get_documentation(name, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0297000" if __import__("os").path.isdir("./environment_mix/0297000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _norm_name(x):
        return x.strip().casefold()

    def _next_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log(endpoint, status, latency_ms, meta=None):
        fname = "request_logs.json"
        if not os.path.exists(os.path.join(_DB, fname)):
            return
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _next_id("req"),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int(latency_ms),
            "timestamp": _now_iso(),
        }
        if isinstance(meta, dict):
            row.update(meta)
        logs.append(row)
        _save(fname, logs)

    t0 = time.time()
    endpoint = "get_documentation"

    if not isinstance(name, str):
        resp = _err("VALIDATION_ERROR", "`name` must be a string.")
        _log(endpoint, "error", (time.time() - t0) * 1000, {"error_code": resp["error"]["code"]})
        return resp
    if not name.strip():
        resp = _err("VALIDATION_ERROR", "`name` must not be empty.")
        _log(endpoint, "error", (time.time() - t0) * 1000, {"error_code": resp["error"]["code"]})
        return resp
    nm = _norm_name(name)

    sources = _load("documentation_sources.json")
    if not isinstance(sources, list):
        sources = []
    src = None
    for r in sources:
        if isinstance(r, dict) and isinstance(r.get("name"), str) and _norm_name(r["name"]) == nm:
            src = r
            break
    if not src:
        resp = _err("NOT_FOUND", f"No documentation source exists with name '{name}'.")
        _log(endpoint, "error", (time.time() - t0) * 1000, {"error_code": resp["error"]["code"]})
        return resp

    src_id = src.get("id")

    # Collect tags
    mappings = _load("documentation_source_tags.json")
    if not isinstance(mappings, list):
        mappings = []
    tag_rows = _load("documentation_tags.json")
    if not isinstance(tag_rows, list):
        tag_rows = []
    tag_by_id = {t.get("id"): t for t in tag_rows if isinstance(t, dict) and t.get("id")}

    tag_texts = []
    for m in mappings:
        if not isinstance(m, dict):
            continue
        if m.get("source_id") != src_id:
            continue
        t = tag_by_id.get(m.get("tag_id"))
        if isinstance(t, dict) and isinstance(t.get("tag"), str):
            tag_texts.append(t["tag"])
    tag_texts = sorted(set(tag_texts))

    out = {"source": src, "tags": tag_texts}
    _log(endpoint, "ok", (time.time() - t0) * 1000, {"source_id": src_id})
    return out

def list_update_jobs(name=None, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0297000" if __import__("os").path.isdir("./environment_mix/0297000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _norm_name(x):
        return x.strip().casefold()

    def _next_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log(endpoint, status_s, latency_ms, meta=None):
        fname = "request_logs.json"
        if not os.path.exists(os.path.join(_DB, fname)):
            return
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _next_id("req"),
            "endpoint": endpoint,
            "status": status_s,
            "latency_ms": int(latency_ms),
            "timestamp": _now_iso(),
        }
        if isinstance(meta, dict):
            row.update(meta)
        logs.append(row)
        _save(fname, logs)

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur.strip():
            return _err("VALIDATION_ERROR", "`cursor` must be a non-empty string when provided.")
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"=" * (-len(cur) % 4))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or "after" not in obj:
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            after = obj["after"]
            if after is not None and (not isinstance(after, str) or not after):
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            return after
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    def _encode_cursor(after_id):
        obj = {"after": after_id}
        raw = json.dumps(obj, ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    t0 = time.time()
    endpoint = "list_update_jobs"

    # Validate filters
    source_id = None
    if name is not None:
        if not isinstance(name, str):
            resp = _err("VALIDATION_ERROR", "`name` must be a string when provided.")
            _log(endpoint, "error", (time.time() - t0) * 1000, {"error_code": resp["error"]["code"]})
            return resp
        if not name.strip():
            resp = _err("VALIDATION_ERROR", "`name` must not be empty when provided.")
            _log(endpoint, "error", (time.time() - t0) * 1000, {"error_code": resp["error"]["code"]})
            return resp
        nm = _norm_name(name)
        sources = _load("documentation_sources.json")
        if not isinstance(sources, list):
            sources = []
        src = None
        for r in sources:
            if isinstance(r, dict) and isinstance(r.get("name"), str) and _norm_name(r["name"]) == nm:
                src = r
                break
        if not src:
            resp = _err("NOT_FOUND", f"No documentation source exists with name '{name}'.")
            _log(endpoint, "error", (time.time() - t0) * 1000, {"error_code": resp["error"]["code"]})
            return resp
        source_id = src.get("id")

    allowed_status = {"queued", "running", "succeeded", "failed", "cancelled"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            resp = _err("VALIDATION_ERROR", "`status` must be one of: queued, running, succeeded, failed, cancelled.")
            _log(endpoint, "error", (time.time() - t0) * 1000, {"error_code": resp["error"]["code"]})
            return resp

    if limit is None:
        limit_v = 50
    else:
        if not isinstance(limit, int):
            resp = _err("VALIDATION_ERROR", "`limit` must be an integer.")
            _log(endpoint, "error", (time.time() - t0) * 1000, {"error_code": resp["error"]["code"]})
            return resp
        if limit < 1 or limit > 200:
            resp = _err("VALIDATION_ERROR", "`limit` must be between 1 and 200.")
            _log(endpoint, "error", (time.time() - t0) * 1000, {"error_code": resp["error"]["code"]})
            return resp
        limit_v = limit

    after_id = None
    dec = _decode_cursor(cursor)
    if isinstance(dec, dict) and dec.get("error"):
        _log(endpoint, "error", (time.time() - t0) * 1000, {"error_code": dec["error"]["code"]})
        return dec
    after_id = dec

    jobs = _load("documentation_update_jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    # Filter
    filtered = []
    for j in jobs:
        if not isinstance(j, dict):
            continue
        if source_id is not None and j.get("source_id") != source_id:
            continue
        if status is not None and j.get("status") != status:
            continue
        filtered.append(j)

    # Sort reverse chronological by created_at then id
    def _sort_key(j):
        dt = _parse_dt(j.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        return (dt, str(j.get("id") or ""))

    filtered.sort(key=_sort_key, reverse=True)

    # Apply cursor (after_id is the last seen id in the sorted order)
    start_idx = 0
    if after_id is not None:
        pos = None
        for i, j in enumerate(filtered):
            if j.get("id") == after_id:
                pos = i
                break
        if pos is not None:
            start_idx = pos + 1
        else:
            # Cursor refers to an item not in this filtered set; treat as validation error
            resp = _err("VALIDATION_ERROR", "Cursor does not match the current result set.")
            _log(endpoint, "error", (time.time() - t0) * 1000, {"error_code": resp["error"]["code"]})
            return resp

    page = filtered[start_idx:start_idx + limit_v]
    has_more = start_idx + limit_v < len(filtered)
    next_cursor = _encode_cursor(page[-1].get("id")) if has_more and page else None

    out = {
        "jobs": page,
        "total": len(filtered),
        "limit": limit_v,
        "has_more": bool(has_more),
        "next_cursor": next_cursor,
    }
    _log(endpoint, "ok", (time.time() - t0) * 1000, {"returned": len(page)})
    return out

def get_update_job(job_id, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0297000" if __import__("os").path.isdir("./environment_mix/0297000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt=None):
        dt = dt or _now()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt
            except Exception:
                return None
        return None

    def _log(status, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        dt = _now()
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": "req_" + dt.strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "get_update_job",
            "tool": "get_update_job",
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "timestamp": _iso(dt),
            "created_at": _iso(dt),
        }
        if isinstance(meta, dict):
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_check():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = _now()
        window = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = _parse_dt(r.get("created_at")) or _parse_dt(r.get("timestamp"))
            if ts and ts >= window:
                cnt += 1
        limit_per_minute = 120
        if cnt >= limit_per_minute:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit_per_minute=limit_per_minute)
        return None

    if not isinstance(job_id, str) or not job_id.strip():
        _log("error", "VALIDATION_ERROR", "job_id must be a non-empty string", {"job_id": job_id})
        return _err("VALIDATION_ERROR", "job_id must be a non-empty string", field="job_id")
    job_id_v = job_id.strip()

    rl = _rate_limit_check()
    if rl:
        _log("error", rl["error"]["code"], rl["error"]["message"])
        return rl

    jobs = _load("documentation_update_jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    job = None
    for j in jobs:
        if isinstance(j, dict) and j.get("id") == job_id_v:
            job = j
            break

    # Backwards-compatible behavior observed in audit: some callers pass a source_id here.
    if job is None:
        sources = _load("documentation_sources.json")
        if not isinstance(sources, list):
            sources = []
        if any(isinstance(s, dict) and s.get("id") == job_id_v for s in sources):
            # find latest job for this source
            latest = None
            latest_dt = None
            for j in jobs:
                if not isinstance(j, dict) or j.get("source_id") != job_id_v:
                    continue
                dt = _parse_dt(j.get("created_at")) or _parse_dt(j.get("updated_at"))
                if latest is None or (dt and (latest_dt is None or dt > latest_dt)):
                    latest = j
                    latest_dt = dt
            if latest is not None:
                job = latest

    if job is None:
        _log("error", "NOT_FOUND", f"No update job exists with id '{job_id_v}'.", {"job_id": job_id_v})
        return _err("NOT_FOUND", f"No update job exists with id '{job_id_v}'.", job_id=job_id_v)

    _log("ok", meta={"job_id": job.get("id")})
    return {"job": job}

def cancel_update_job(job_id, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0297000" if __import__("os").path.isdir("./environment_mix/0297000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt=None):
        dt = dt or _now()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.fromtimestamp(v, tz=datetime.timezone.utc)
            except Exception:
                return None
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt
            except Exception:
                return None
        return None

    def _log(status, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        dt = _now()
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": "req_" + dt.strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "cancel_update_job",
            "tool": "cancel_update_job",
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "timestamp": _iso(dt),
            "created_at": _iso(dt),
        }
        if isinstance(meta, dict):
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_check():
        # Service-level limit: 60 mutations/min across add/update/remove/cancel.
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = _now()
        window_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ep = r.get("endpoint") or r.get("tool")
            if ep not in ("add_documentation", "update_documentation", "remove_documentation", "cancel_update_job"):
                continue
            dt = _parse_dt(r.get("created_at") or r.get("timestamp"))
            if not dt:
                continue
            if dt >= window_start:
                cnt += 1
        if cnt >= 60:
            return _err("RATE_LIMIT", "Rate limit exceeded: max 60 mutations per minute.")
        return None

    # Validate
    if not isinstance(job_id, str) or not job_id.strip():
        e = _err("VALIDATION_ERROR", "`job_id` is required and must be a non-empty string.", field="job_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e
    job_id = job_id.strip()

    rl = _rate_limit_check()
    if rl:
        _log("error", rl["error"]["code"], rl["error"]["message"])
        return rl

    jobs = _load("documentation_update_jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    job = None
    for r in jobs:
        if isinstance(r, dict) and r.get("id") == job_id:
            job = r
            break

    # Audit defect shows callers sometimes pass a source_id into cancel_update_job; resolve to active queued/running job.
    if job is None:
        if job_id.startswith("cdx_src_"):
            src_id = job_id
            candidates = []
            for r in jobs:
                if not isinstance(r, dict):
                    continue
                if r.get("source_id") != src_id:
                    continue
                if r.get("status") in ("queued", "running"):
                    candidates.append(r)
            if candidates:
                candidates.sort(key=lambda x: _parse_dt(x.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), reverse=True)
                job = candidates[0]

    if job is None:
        e = _err("NOT_FOUND", "No update job exists with the provided identifier.", field="job_id")
        _log("error", e["error"]["code"], e["error"]["message"])
        return e

    status = job.get("status")
    if status not in ("queued", "running"):
        e = _err("CONFLICT", "Update job cannot be cancelled because it is already in a terminal state.", current_status=status)
        _log("error", e["error"]["code"], e["error"]["message"], meta={"job_id": job.get("id"), "current_status": status})
        return e

    # Transition: queued/running -> cancelled
    now = _now()
    job["status"] = "cancelled"
    if status == "running" and not job.get("started_at"):
        job["started_at"] = _iso(now)
    job["finished_at"] = _iso(now)
    job["updated_at"] = _iso(now)
    if not job.get("error_message"):
        job["error_message"] = "Cancelled by user request."

    _save("documentation_update_jobs.json", jobs)

    _log("ok", meta={"job_id": job.get("id"), "previous_status": status})
    return {"data": job}

def list_documents(name, status=None, language=None, include_content=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0297000" if __import__("os").path.isdir("./environment_mix/0297000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    def _record_request(endpoint, status_s, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        dt = datetime.datetime.utcnow()
        latency_ms = int((dt - t0).total_seconds() * 1000)
        row = {
            "id": f"req_{dt.strftime('%Y%m%d%H%M%S')}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": dt.replace(microsecond=0).isoformat() + "Z",
            "meta": meta or {},
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _norm_name(s):
        return s.strip().casefold()

    def _parse_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur.strip():
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            txt = raw.decode("utf-8")
            if not txt.startswith("offset:"):
                return None
            off = int(txt.split("offset:", 1)[1])
            if off < 0:
                return None
            return off
        except Exception:
            return None

    def _make_cursor(off):
        txt = f"offset:{off}".encode("utf-8")
        return base64.urlsafe_b64encode(txt).decode("utf-8").rstrip("=")

    # Validate inputs
    if not isinstance(name, str) or not name.strip():
        _record_request("list_documents", "error", "VALIDATION_ERROR", {"name": name})
        return _err("VALIDATION_ERROR", "name must be a non-empty string")

    if status is not None and status not in ("active", "stale", "deleted"):
        _record_request("list_documents", "error", "VALIDATION_ERROR", {"status": status})
        return _err("VALIDATION_ERROR", "Invalid status filter", allowed=["active", "stale", "deleted"])

    if language is not None and (not isinstance(language, str) or not language.strip()):
        _record_request("list_documents", "error", "VALIDATION_ERROR", {"language": language})
        return _err("VALIDATION_ERROR", "language must be a non-empty string when provided")

    if include_content is None:
        include_content = False
    if not isinstance(include_content, bool):
        _record_request("list_documents", "error", "VALIDATION_ERROR", {"include_content": include_content})
        return _err("VALIDATION_ERROR", "include_content must be a boolean")

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        _record_request("list_documents", "error", "VALIDATION_ERROR", {"limit": limit})
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        _record_request("list_documents", "error", "VALIDATION_ERROR", {"limit": limit})
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200", minimum=1, maximum=200)

    offset = _parse_cursor(cursor)
    if offset is None:
        _record_request("list_documents", "error", "VALIDATION_ERROR", {"cursor": cursor})
        return _err("VALIDATION_ERROR", "Invalid cursor")

    # Resolve source by authoritative name (case-insensitive)
    sources = _load("documentation_sources.json")
    if not isinstance(sources, list):
        sources = []
    target = None
    nname = _norm_name(name)
    for s in sources:
        if isinstance(s, dict) and isinstance(s.get("name"), str) and _norm_name(s["name"]) == nname:
            target = s
            break
    if target is None:
        _record_request("list_documents", "error", "NOT_FOUND", {"name": name})
        return _err("NOT_FOUND", "No documentation source found with that name", name=name)

    source_id = target.get("id")

    # Read documents and filter
    docs = _load("documentation_documents.json")
    if not isinstance(docs, list):
        docs = []

    filtered = []
    for d in docs:
        if not isinstance(d, dict):
            continue
        if d.get("source_id") != source_id:
            continue
        if status is not None and d.get("status") != status:
            continue
        if language is not None:
            lang = d.get("language")
            if not isinstance(lang, str) or lang.strip() != language.strip():
                continue
        filtered.append(d)

    # Stable ordering: canonical_url asc, chunk_index asc, id asc
    def _key(d):
        cu = d.get("canonical_url") or ""
        ci = d.get("chunk_index")
        try:
            ci = int(ci)
        except Exception:
            ci = 0
        return (cu, ci, d.get("id") or "")
    filtered.sort(key=_key)

    total = len(filtered)
    page = filtered[offset:offset + limit]
    has_more = offset + limit < total
    next_cursor = _make_cursor(offset + limit) if has_more else None

    # Shape output; optionally drop content_text
    out_docs = []
    for d in page:
        row = dict(d)
        if not include_content:
            row.pop("content_text", None)
        out_docs.append(row)

    _record_request(
        "list_documents",
        "success",
        None,
        {"name": name, "source_id": source_id, "status": status, "language": language, "limit": limit, "offset": offset},
    )
    return {
        "source": {"id": target.get("id"), "name": target.get("name"), "url": target.get("url"), "category": target.get("category")},
        "documents": out_docs,
        "pagination": {"total": total, "limit": limit, "cursor": cursor, "next_cursor": next_cursor, "has_more": has_more},
    }
